UPDATE scm02_sr_appr_step
   SET scm02_step_status_cd = #{stepStatusCd},
       scm02_appr_date      = now(),
       scm02_appr_emp_id    = #{apprEmpId}
 WHERE scm02_sr_appr_step_id = #{srApprStepId}

UPDATE scm02_sr_appr_step
   SET scm02_note          = #{note},
       scm02_reject_reason = #{rejectReason}
 WHERE scm02_sr_appr_step_id = #{srApprStepId}
